sp_widget.client_script:
api.controller = function($timeout) { 
  var c = this;

  console.log("Snake game controller loaded");

  const levels = c.data.levels;//Levels are stored on the server side initially


  $timeout(function() {

    const snakeLayer = document.getElementById('snake-layer'); // for snake & food
    const animationLayer = document.getElementById('animation-layer'); // new layer for food animation

    const gameWidth = 300;
    const gameHeight = 300;
    const gridSize = 10;

    let snake = [{
      x: Math.floor(gameWidth / (2 * gridSize)) * gridSize,
      y: Math.floor(gameHeight / (2 * gridSize)) * gridSize,
	  glow: 0,
	  color: "hsl(120, 100%, 60%)"
    }];

    const directions = ['UP','RIGHT','DOWN','LEFT'];
    let dirIndex = 1; //Starting facing right

    let score = 0;
    let gameOver = false;
	let foodEaten = false;
	let growSegments = 0;
	let gamePaused = false;

    let currentLevel = 0;
    let obstacles = levels[currentLevel].obstacles;
	let isAnimatingObstacles = false;

    let food = randomFood();

	let gameInterval = null;

waitForAnime(() => {
  // Show main overlay
  showOverlayMessage("Play Snake!", {
    color: "white",
    onClose: () => {
      const firstLevelObstacles = levels[currentLevel].obstacles;

      // Animate obstacles first
      animateObstacles(firstLevelObstacles, () => {
        obstacles = firstLevelObstacles;

        // ✅ Start game loop only now
        if (!gameInterval) {
          gameInterval = setInterval(gameLoop, 100);
        }

        gamePaused = false; // finally let snake move
      });
    }
  });

  // Show intro message
  showInlineMessage(
    "Use the <b>space bar</b> to start the game or click. <br>Use <b><- and -> </b> <br>keys  or click on the <br><b>left</b> or <b>right</b> <br>of the screen on your mobile to turn.",
    { duration: 3000, color: "black",  html: true }
  );
});




    function gameLoop() {

		if(gamePaused) return;
		if (gameOver) return;
		move();
		draw();
    }


function randomFood() {
  let newFood;
  let isOnSnake, isOnObstacle;

	if (isAnimatingObstacles) {

    return null; // caller should retry later. Food always waits for obstacle animation to complete
  }

  do {
    newFood = {
      x: getRandomCoord(gameWidth),
      y: getRandomCoord(gameHeight)
    };

    isOnSnake = snake.some(seg => seg.x === newFood.x && seg.y === newFood.y);
    isOnObstacle = (obstacles && obstacles.length > 0) 
                   ? obstacles.some(block => block.x === newFood.x && block.y === newFood.y)
                   : false;
  } while (isOnSnake || isOnObstacle);

  return newFood;
}
    function draw() {

			snakeLayer.innerHTML = ''; // clear snake layer each frame


      // Draw snake
      snake.forEach(segment => {
        const el = document.createElement('div');
        el.className = 'snake';
        el.style.left = segment.x + 'px';
        el.style.top = segment.y + 'px';


		if (segment.glow > 0) {
			el.style.boxShadow = '0 0 ' + (4 + segment.glow * 2)  + 'px lime';
			// Color effect driven by glow
    		// Map glow → hue (e.g. green → yellow → red → purple → back)
    		const hue = 120 - segment.glow * 10; 
			el.style.backgroundColor = "hsl(" + ((hue + 360)%360) + ",100% ,60%)";

			segment.glow--; // decrease glow per frame
			} else {
				el.style.boxShadow = 'none';
				el.style.backgroundColor = 'hsl(120, 100%, 60%)'; // base green
				}
		if (segment.glow > 0) {
			el.style.boxShadow = '0 0 8px lime';
			segment.glow--; // reduce glow each frame
			} else {
        el.style.boxShadow = 'none';
    }	

		segment.el = el;
        snakeLayer.appendChild(el);
      });

      // Draw obstacles (still on gameArea for simplicity)
      obstacles.forEach(block => {
        const Obsel = document.createElement('div');
        Obsel.className = 'obstacle';
        Obsel.style.left = block.x + 'px';
        Obsel.style.top = block.y + 'px';
		Obsel.style.backgroundColor = block.color;
       snakeLayer.appendChild(Obsel); // put on same layer for alignment
      });

      // Draw food
	  if (!foodEaten) {
      const foodEl = document.createElement('div');
      foodEl.className = 'food';
      foodEl.style.left = food.x + 'px';
      foodEl.style.top = food.y + 'px';
      snakeLayer.appendChild(foodEl); // keep food on snakeLayer so it moves correctly
	  }

    }

    function move() {

      const head = { ...snake[0] };
      const direction = directions[dirIndex];

      let nextX = head.x;
      let nextY = head.y;

      if (direction === 'RIGHT') nextX += gridSize;
      if (direction === 'LEFT') nextX -= gridSize;
      if (direction === 'UP') nextY -= gridSize;
      if (direction === 'DOWN') nextY += gridSize;

      // Wall collision
      if (head.x <= 0 || head.y <= 0 || head.x >= gameWidth - gridSize || head.y >= gameHeight - gridSize) {
		console.log('COLLISION:: XY, WALLXY::' + head.x + ',' + head.y + ':::' + gameWidth + ',' + gameHeight);
        endGame();
        return;
      }

      head.x = nextX;
      head.y = nextY;

      // Obstacle collision
      if (obstacles.some(block => block.x === head.x && block.y === head.y)) {
        endGame();
        return;
      }

      // Self collision
      if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
        endGame();
        return;
      }

      snake.unshift(head);

      // Food collision
      if (head.x === food.x && head.y === food.y) {
        score++;
		foodEaten = true;

        // --- NEW: Animate food using temporary div in animationLayer ---
        animateFoodEat(food.x, food.y, () => {
          food = randomFood(); // Generate new food after animation
		  foodEaten = false;
        });

		snake.forEach((seg, index) => {
        setTimeout(() => {
            seg.glow = 5; // number of frames to glow
        }, index * 50); // 50ms stagger for each segment
    });

		growSegments += 3;

        // Level up every 5 points
        if (score % 5 === 0) {
			handleLevelUp();  

}

      } else {
			if (growSegments > 0) {
			growSegments--;
			} else {


        snake.pop();
      }
    }
	}
    function endGame() {
		gameOver = true;
		gamePaused = true; 
		clearInterval(gameInterval);
		gameInterval = null;

		runLoseAnimation();

	  showOverlayMessage("Thank you for playing!", {
  color: "white"});

  // compute levelsCompleted array from score
const pointsPerLevel = 5; // how many points per level to consider "full"
const fullLevels = Math.floor(score / pointsPerLevel);
const lastLevelPoints = score % pointsPerLevel;

const levelsCompletedArr = [];
for (let i = 0; i < fullLevels; i++) levelsCompletedArr.push(pointsPerLevel);
if (lastLevelPoints > 0) levelsCompletedArr.push(lastLevelPoints);

// show share UI
showShareResults(levelsCompletedArr);

}

    function getRandomCoord(max) {
      const cells = Math.floor(max / gridSize -2);
      const index = Math.floor(Math.random() * cells + 1);
      return index * gridSize;
    }


    // --- NEW: Animate food with temporary div ---
    function animateFoodEat(x, y, onComplete) {
		const animDiv = document.createElement('div');
		animDiv.className = 'food';
		animDiv.style.left = x + 'px';
		animDiv.style.top  = y + 'px';
		animationLayer.appendChild(animDiv);

		anime({
			targets: animDiv,
			scale: [
				{ value: 1.5, duration: 400, easing: 'easeOutElastic(1, .6)' },
				{ value: 1, duration: 600, easing: 'easeOutElastic(1, .6)' }
				],
			backgroundColor: [
			{ value: '#FF0000', duration: 25 },   // start red
			{ value: '#FFD700', duration: 25 },   // then yellow
			{ value: '#FFFFFF', duration: 25 }    // then white
			],
			opacity: [
				{ value: 1, duration: 0 },             // fully visible at start
				{ value: 0, duration: 200, delay: 400 } // fade out after color sequence
  ],
		easing: 'linear',
    // fade out after the bounce finishes
        complete: () => {
          animDiv.remove(); // remove temporary div
          if (onComplete) onComplete();
        }
      });
    }



function handleLevelUp() {

	console.log('handleLevelUp:: ' + currentLevel);

  // Move to next level
  currentLevel++;

  // Stop snake movement while transitioning
  gamePaused = true;
  clearInterval(gameInterval);
  gameInterval = null;

  runWinAnimation().then(() => {
    // After animation finishes, reset snake
	let centerX = Math.floor(gameWidth / (2 * gridSize)) * gridSize;
    let centerY = Math.floor(gameHeight / (2 * gridSize)) * gridSize;
    snake = [{ x: centerX, y: centerY, glow: 0 }];
    dirIndex = 1;
    growSegments = 0;

// Show LEVEL READY messagee
    showInlineMessage("Level " + (currentLevel) + "<b> ready! </b>",{ duration: 2000, color: "black",  html: true}); 


        const nextObstacles = levels[currentLevel].obstacles;

        // Animate obstacles first
		animateObstacles(nextObstacles, () => {
			obstacles = nextObstacles;
			ensureFoodSpawn();

		// Ensure game loop is running
		if (!gameInterval) {
			gameInterval = setInterval(gameLoop, 100);
			}

          gamePaused = false; // resume snake movement
        });
    });

}


function runWinAnimation() {
	snakeLayer.innerHTML = ""; //clear snake layer too
  return new Promise(resolve => {

    const animLayer = document.getElementById('animation-layer');
    animLayer.innerHTML = ""; // clear previous animations

    // Generate 10 rainbow HSL colors
    const colors = [];
    for (let i = 0; i < 10; i++) {
      const hue = (i * 36) % 360; // 20 steps around the color wheel
      colors.push({ backgroundColor: "hsl(" + hue + ", 100%, 60%)" });
    }

    const totalSegments = snake.length;
    let completedSegments = 0;

    snake.forEach((seg, i) => {
      const clone = document.createElement('div');
      clone.className = 'snake';
      clone.style.left = seg.x + 'px';
      clone.style.top = seg.y + 'px';
      clone.style.backgroundColor = 'hsl(120, 100%, 60%)'; // starting color
      animLayer.appendChild(clone);

      anime({
        targets: clone,
        scale: [
          { value: 1.5, duration: 500, easing: 'easeOutQuad' },
          { value: 1.0, duration: 500, easing: 'easeInOutSine' }
        ],
        keyframes: colors,
        delay: i * 25,      // stagger to propagate along the snake
        duration: 200,       // full color cycle per loop
        loop: 1,             // run twice
        easing: 'linear',
		begin: () => {
    // remove that segment from the real snake layer when animation begins
			if (seg.el) {
				seg.el.remove();
				seg.el = null; // clear reference
      }
  		},
        complete: () => {
          clone.remove();
          completedSegments++;
          if (completedSegments === totalSegments) {
            animLayer.innerHTML = ""; // clear animation layer

            resolve();
          }
        }
      });
    });
  });
}


function runLoseAnimation() {
  snakeLayer.innerHTML = ""; // clear snake layer too
  return new Promise(resolve => {
    const animLayer = document.getElementById('animation-layer');
    animLayer.innerHTML = ""; // clear previous animations

    const totalSegments = snake.length;
    let completedSegments = 0;

    snake.forEach((seg, i) => {
      const clone = document.createElement('div');
      clone.className = 'snake';
      clone.style.left = seg.x + 'px';
      clone.style.top = seg.y + 'px';
      clone.style.backgroundColor = 'hsl(120, 100%, 60%)'; // start green
      animLayer.appendChild(clone);

      anime({
        targets: clone,
        delay: i * 100, // stagger more clearly
        keyframes: [
          { backgroundColor: 'hsl(120, 100%, 60%)', scale: 1.1, duration: 200, easing: 'easeOutQuad' },
          { backgroundColor: 'hsl(0, 0%, 50%)', scale: 0.5, duration: 600, easing: 'easeInOutSine' },
          { opacity: 0, duration: 300, easing: 'linear' } // fade away
        ],
		begin: () => {
    // remove that segment from the real snake layer when animation begins
			if (seg.el) {
				seg.el.remove();
				seg.el = null; // clear reference
      }
  		},
        complete: () => {
          clone.remove();
          completedSegments++;
          if (completedSegments === totalSegments) {
            animLayer.innerHTML = ""; 
            resolve();
          }
        }
      });
    });
  });
}


function animateObstacles(levelObstacles, onComplete) {
	console.log('animateObstalces:::' + levelObstacles);
	isAnimatingObstacles = true;
	gamePaused  = true;
    const animLayer = document.getElementById('animation-layer');

    if (animLayer) animLayer.innerHTML = ""; // clear any previous animations
	obstacles = [...levelObstacles]

	snakeLayer.querySelectorAll('.obstacle').forEach(el => el.remove()); // remove visuals too
    const obstacleEls = [];

    levelObstacles.forEach((block) => {
        const el = document.createElement('div');
        el.className = 'obstacle';
        el.style.left = block.x + 'px';
        el.style.top = block.y + 'px';
		el.style.backgroundColor = block.color;
        el.style.transform = 'scale(0)';
        animLayer.appendChild(el);
        obstacleEls.push(el);
    });

    anime({
        targets: obstacleEls,
        scale: 1,
        easing: 'easeOutBack',
        duration: 50,
        delay: anime.stagger(20),
        complete: () => {
            animLayer.innerHTML = "";        // remove animation elements
			console.log('AnimateOstacles complete - new level obstacless:::' + obstacles);
            if (onComplete) onComplete();
			isAnimatingObstacles = false;
			gamePaused = false;
        }
    });
}


// 🔹 Overlay message (pauses game until dismissed)
function showOverlayMessage(text, options = {}) {
  const overlay = document.getElementById("message-overlay");
  const gameArea = document.getElementById("game-area");

  overlay.innerHTML = "";
  overlay.classList.add("active");

  // Pause game
  gamePaused = true;

  const span = document.createElement("span");
  span.textContent = text;
  span.style.display = "inline-block";
  span.style.color = options.color || "lime";
  span.style.fontSize = options.fontSize || "28px";
  overlay.appendChild(span);

  // Animate in
  anime({
    targets: span,
    opacity: [0, 1],
    translateY: [30, 0],
    easing: "easeOutBack",
    duration: options.duration || 600
  });

  function closeMessage() {
    overlay.classList.remove("active");
    overlay.innerHTML = "";
    gamePaused = false;

    // Remove listeners
    document.removeEventListener("keydown", onDismiss);
    gameArea.removeEventListener("click", onDismiss);
    gameArea.removeEventListener("touchstart", onDismiss);

    if (typeof options.onClose === "function") options.onClose();
  }

  function onDismiss(e) {
    if (e.type === "keydown" && (e.code === "Space" || e.key === " ")) {
      e.preventDefault();
      closeMessage();
    }
    if (e.type === "click" || e.type === "touchstart") {
      closeMessage();
    }
  }

  // Add listeners for dismiss
  document.addEventListener("keydown", onDismiss);
  gameArea.addEventListener("click", onDismiss);
  gameArea.addEventListener("touchstart", onDismiss);
}




// message: string (plain or html if html=true)
// options: { duration: number (ms, 0 => persistent), html: boolean, onClose: fn }
function showInlineMessage(message, options = {}) {
  const messageArea = document.getElementById("level-message");
  if (!messageArea) return;

  const duration = (options.duration !== undefined) ? options.duration : 3000;
  const allowHTML = !!options.html;

  // make sure parent is visible (in case prior code left inline opacity/transform)
  messageArea.style.opacity = '';
  messageArea.style.transform = '';

  // remove any previous ephemeral message box (but keep share-container if present)
  const prev = messageArea.querySelector('.inline-message');
  if (prev) prev.remove();

  // create child box and animate that
  const box = document.createElement('div');
  box.className = 'inline-message';
  if (allowHTML) box.innerHTML = message;
  else box.textContent = message;

  // append and animate the child
  messageArea.appendChild(box);

  anime({
    targets: box,
    opacity: [0, 1],
    translateY: [8, 0],
    scale: [0.98, 1],
    easing: 'easeOutBack',
    duration: 320
  });

  // auto-remove only if duration > 0
  if (duration > 0) {
    setTimeout(() => {
      anime({
        targets: box,
        opacity: [1, 0],
        translateY: [0, 8],
        scale: [1, 0.98],
        easing: 'easeInBack',
        duration: 240,
        complete: () => {
          if (box && box.parentNode) box.parentNode.removeChild(box);
          if (typeof options.onClose === 'function') options.onClose();
        }
      });
    }, duration);
  }

  return box;
}




// levelsCompleted: Array<number> (or a string/HTML fallback)
function showShareResults(levelsCompleted) {
  const messageArea = document.getElementById('level-message');
  if (!messageArea) {
    console.warn('No #level-message found');
    return;
  }

  // ensure parent is visible (clear any leftover inline animation styles)
  messageArea.style.opacity = '';
  messageArea.style.transform = '';
  messageArea.style.height = 'auto';

  // reuse existing share-container inside messageArea, or create it if absent
  let shareContainer = messageArea.querySelector('#share-container');
  if (!shareContainer) {
    shareContainer = document.createElement('div');
    shareContainer.id = 'share-container';
    messageArea.appendChild(shareContainer);
  } else {
    shareContainer.innerHTML = ''; // clear old content
    shareContainer.style.display = 'flex';
  }

// Build preview HTML if array passed
let previewHtml = '';
if (Array.isArray(levelsCompleted)) {
  previewHtml = levelsCompleted
    .map((v) => {
      const safeVal = Math.max(0, Math.min(Number(v) || 0, 5)); // max 5 squares
      if (safeVal === 5) {
        return '🟩🟩🟩🟩🟩✅';
      } else {
        const greenSquares = '🟩'.repeat(safeVal);
        const blackSquares = '⬛'.repeat(5 - safeVal);
        return greenSquares + blackSquares + '❌';
      }
    })
    .join('\n');
} else if (typeof levelsCompleted === 'string') {
  previewHtml = levelsCompleted;
} else {
  previewHtml = '<em>No results</em>';
}

  // Fill container (styling is in CSS)
  shareContainer.innerHTML = '<button id="share-btn" type="button">Share My Results</button>';

  // Animate only the share container (not messageArea)
  anime({
    targets: shareContainer,
    opacity: [0, 1],
    translateY: [10, 0],
    duration: 350,
    easing: 'easeOutCubic'
  });

  // Attach handler for copy
  const shareBtn = shareContainer.querySelector('#share-btn');
  if (shareBtn) {
    shareBtn.onclick = () => {
      let textToCopy;
	  textToCopy = previewHtml;

      navigator.clipboard.writeText(textToCopy).then(() => {
        showInlineMessage('✅ Results copied to clipboard!', { duration: 2000 });
      }).catch(err => {
        console.error('Copy failed', err);
        showInlineMessage('⚠️ Could not copy results.', { duration: 2000 });
      });
    };
  }
	logResults(previewHtml);

  return shareContainer;
}





function ensureFoodSpawn() {
  if (isAnimatingObstacles) {
    // wait until animation ends
    setTimeout(ensureFoodSpawn, 100);
    return;
  }
  let newF;
  do {
    newF = randomFood();
  } while (!newF);
  food = newF;
}


function waitForAnime(callback) {
  if (typeof anime !== "undefined") {
    callback();
  } else {
    setTimeout(() => waitForAnime(callback), 50); // retry every 50ms
  }
}


function logResults(myResults){
		console.log('logResults::: ' + myResults);

		c.data.action = "logResults";
		c.data.results = myResults;
		c.data.userAgent = navigator.userAgent;
		c.server.update();

}


    document.addEventListener('keydown', e => {
      if(e.key === 'ArrowLeft'){
        dirIndex = (dirIndex + 3) % 4; // wrap left
      }
      if(e.key === 'ArrowRight'){
        dirIndex = (dirIndex +1 ) % 4; // wrap right
      }

	  if (e.key === ' ' && gamePaused){
		console.log('SPCAE BAR UNPAUSE');
		const overlay = document.getElementById("message-overlay");
		overlay.classList.remove("active");
		gamePaused = false;
		 }

    });

	const gameWrapper = document.getElementById("game-wrapper");


function handleClickOrTap(e) {
  if (gameOver || gamePaused) return;

  let x;
  if (e.type === "touchstart") {
    x = e.touches[0].clientX; // finger pos
  } else {
    x = e.clientX; // mouse click pos
  }

  const screenWidth = window.innerWidth;
  const isLeftSide = x < screenWidth / 2;

  if (isLeftSide) {
    dirIndex = (dirIndex + 3) % 4; // turn left
  } else {
    dirIndex = (dirIndex + 1) % 4; // turn right
  }
}


gameWrapper.addEventListener("pointerup", handleClickOrTap);


gameWrapper.addEventListener("click", () => {
		if (gamePaused) {
			const overlay = document.getElementById("message-overlay");
			console.log('gameWRAPPER - removing gamePaused');
			overlay.classList.remove("active");
			gamePaused = false;
  }
});


  }, 0);


};

sp_widget.css:
/* ------------------------------
   Center the entire game container
--------------------------------*/
#game-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;      /* horizontal center */
  justify-content: center;  /* vertical center */
  min-height: 100vh;        /* fill screen height */
  box-sizing: border-box;
}


#game-area {
  position: relative;
  width: 300px;
  height: 300px;
  box-sizing: border-box; /* include border in width/height */
  overflow: hidden;  
  background: 
    radial-gradient(
      #000 0%,
      #000 40%,
      #4B4B4B 100%); 
}



#level-message {
  display: flex;
  width: 300px;       
  height: 60px;       
  text-align: center;
  position: relative;
  display: block;
}

#snake-layer, #animation-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  background: transparent;

}

#snake-layer{
	border: 5px solid #81B5A1
}



#animation-layer {
/* border: 1px solid red */
}



#message-overlay {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;                /* lay out letters side by side */
  justify-content: center;      /* center horizontally */
  align-items: center;          /* center vertically */
  flex-wrap: wrap;              /* wrap long words to next line */
  max-width: 90%;               /* keep inside playfield */
  max-height: 90%;
  overflow: hidden;             /* prevent spill */
  text-align: center;
  z-index: 999;
}

#message-overlay .message-letter {
  display: inline-block;
  font-weight: bold;
  margin: 0 2px;
  white-space: pre;             /* preserve spaces */
}

#message-overlay.active {
  display: flex;
}
#message-overlay span {
  opacity: 0;
}


.snake, .food, .obstacle {
  position: absolute;
  width: 10px;   /* match gridSize */
  height: 10px;  /* match gridSize */
  transform: translate(-50%, -50%);
  background: lime;
}



.food {
  background: red;
}

.obstacle {
  background-color: gray;
}



/* ------------------------------
   Share / Restart Buttons (Game Over)
--------------------------------*/
#share-container {

  display: flex;   /* hidden until game over */
  flex-direction: column;
  align-items: center;
  gap: 10px;
  width: 100%;
  max-width: 300px;
  padding: 5px 0px;   /* 10px top/bottom, 15px left/right */
}

#share-container button {
  width: 100%;
  padding: 6px 0;       /* smaller, Wordle-like */
  font-size: 16px;
/*  font-weight: bold;*/
  border-radius: 4px;
  border: none;
/*  background: #d3d6da;*/
  color: black;
  cursor: pointer;
  box-shadow: none;     /* remove shadows */
}

#share-container button:hover {
  background: #b9bbc0;
}

#share-container button:active {
  background: #a4a6aa;
}
